// Function to render the 3D scene
void display() {
    glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT); // Clear color and depth buffers
    glLoadIdentity(); //  Reset transformations, as we want a clean starting point

    // Move camera backward along z-axis so cube is visible
    glTranslatef(0.0f, 0.0f, -6.0f);

    // Rotate cube for better 3D visualization
    glRotatef(40, 1.0, 1.0, 0.0); // Angle 40 degrees around x and y axes. means: rotate 40° around the axis (1,1,0).

    // Start defining the cube faces
    glBegin(GL_QUADS); // Using quads (4 vertices per face)

    // Front face (z = 1)
    glColor3f(1, 0, 0); // Red color
    glVertex3f(-1, -1,  1); // Bottom-left vertex
    glVertex3f( 1, -1,  1); // Bottom-right vertex
    glVertex3f( 1,  1,  1); // Top-right vertex
    glVertex3f(-1,  1,  1); // Top-left vertex

    // Back face (z = -1)
    glColor3f(0, 1, 0); // Green color
    glVertex3f(-1, -1, -1); // Bottom-left
    glVertex3f(-1,  1, -1); // Top-left
    glVertex3f( 1,  1, -1); // Top-right
    glVertex3f( 1, -1, -1); // Bottom-right

    // Left face (x = -1)
    glColor3f(0, 0, 1); // Blue color
    glVertex3f(-1, -1, -1); // Back-bottom
    glVertex3f(-1, -1,  1); // Front-bottom
    glVertex3f(-1,  1,  1); // Front-top
    glVertex3f(-1,  1, -1); // Back-top

    // Right face (x = 1)
    glColor3f(1, 1, 0); // Yellow color
    glVertex3f(1, -1, -1); // Back-bottom
    glVertex3f(1, -1,  1); // Front-bottom
    glVertex3f(1,  1,  1); // Front-top
    glVertex3f(1,  1, -1); // Back-top

    // Top face (y = 1)
    glColor3f(0, 1, 1); // Cyan color
    glVertex3f(-1, 1, -1); // Back-left
    glVertex3f(-1, 1,  1); // Front-left
    glVertex3f( 1, 1,  1); // Front-right
    glVertex3f( 1, 1, -1); // Back-right

    // Bottom face (y = -1)
    glColor3f(1, 0, 1); // Magenta color
    glVertex3f(-1, -1, -1); // Back-left
    glVertex3f(-1, -1,  1); // Front-left
    glVertex3f( 1, -1,  1); // Front-right
    glVertex3f( 1, -1, -1); // Back-right

    glEnd(); // End of cube faces

    glutSwapBuffers(); // swaps the back buffer with the front buffer.
}

