// Called when window is resized
void reshape(int w, int h) {
    glViewport(0, 0, w, h); // Set viewport to entire window
    //(First 0: starting x-coordinate. Second 0: starting y-coordinate. w: viewport width. h: viewport height.)
    glMatrixMode(GL_PROJECTION); // Switch to projection matrix
    glLoadIdentity(); // Reset projection matrix
    gluPerspective(45, (float)w / (float)h, 1, 100); // Perspective projection: fov=45°, aspect ratio, near=1, far=100
    glMatrixMode(GL_MODELVIEW); //After projection setting, Switch back to modelview matrix
}

