/* Display callback function – runs whenever the window needs to be redrawn */
void display() {
// GL_COLOR_BUFFER_BIT tells glClear() to erase the previous color/picture from the screen before drawing the new one.
   glClear(GL_COLOR_BUFFER_BIT);    // Clear the screen (color buffer)

   glLoadIdentity();                // Reset any previous transformations

   //translation simply means: Changing an object's position from (x,y)
   //to another position without changing its size, shape, or orientation.

   // ---- First Quad ----
   glTranslatef(+0.0f, 0.0f, 0.0f); // No movement, stays at center
   glBegin(GL_QUADS);              // Start drawing a quadrilateral (4-sided shape)
      glColor3f(1.0f, 0.0f, 0.0f); // Set color to red
      glVertex2f(-0.1f, -0.1f);    // Bottom-left corner
      glVertex2f( 0.1f, -0.1f);    // Bottom-right corner
      glVertex2f( 0.1f,  0.1f);    // Top-right corner
      glVertex2f(-0.1f,  0.1f);    // Top-left corner
   glEnd();                        // End of quad drawing


   // ---- Second Quad ----
   glTranslatef(+0.3f, 0.1f, 0.0f); // Move right (x) and up (y)
   glBegin(GL_QUADS);              // Start new quad
      glColor3f(1.0f, 0.0f, 0.0f); // Red color
      glVertex2f(-0.1f, -0.1f);    // Bottom-left
      glVertex2f( 0.1f, -0.1f);    // Bottom-right
      glVertex2f( 0.1f,  0.1f);    // Top-right
      glVertex2f(-0.1f,  0.1f);    // Top-left
   glEnd();                        // End of second quad

   glLoadIdentity();               // Reset again (important before new transform). “OpenGL remembers the last move. If you don’t reset it, the next object inherits all previous movements.”

   // ---- Third Quad ----
   glTranslatef(-0.3f, -0.1f, 0.0f); // Move left (x) and down (y)
   glBegin(GL_QUADS);               // Start new quad
      glColor3f(1.0f, 0.0f, 0.0f);  // Red again
      glVertex2f(-0.1f, -0.1f);     // Bottom-left
      glVertex2f( 0.1f, -0.1f);     // Bottom-right
      glVertex2f( 0.1f,  0.1f);     // Top-right
      glVertex2f(-0.1f,  0.1f);     // Top-left
   glEnd();                         // End of third quad

   glFlush(); // Execute all the drawing commands that have given so far
}





