{   // GL_COLOR_BUFFER_BIT tells glClear() to erase the previous color/picture from the screen before drawing the new one.
    glClear(GL_COLOR_BUFFER_BIT);
    glLoadIdentity();             // Reset the current transformation

    glRotatef(i, 0.0, 0.0, 1.0);  // Rotate by 'i' degrees. i is the angle Because i is changing over time.
    //in 2D rotation, the object lies in the XY-plane, and rotation happens around the Z-axis.

    // Draw roof (triangle)
    glColor3f(1.0f, 0.0f, 0.0f);  // Red color for roof
    glBegin(GL_TRIANGLES);
        glVertex2f(-0.35f, 0.1f);  // Left corner of roof base
        glVertex2f( 0.35f, 0.1f);  // Right corner of roof base
        glVertex2f( 0.0f,  0.5f);  // Top of roof
    glEnd();

    i += 0.2f;   // Slowly increase rotation angle

    glFlush();                 // Show the drawing

}

