#include <GL/glut.h>
float angle = 0.0;

void init() {
    glEnable(GL_DEPTH_TEST);
    glClearColor(0.1f, 0.1f, 0.1f, 1.0f);

    glMatrixMode(GL_PROJECTION);
    glLoadIdentity();
    gluPerspective(45.0, 1.0, 1.0, 50.0); //How we view the 3D world
    glMatrixMode(GL_MODELVIEW);
}

void display() {
    glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT);
    glLoadIdentity();

    // Move object back into the screen
    glTranslatef(0.0f, 0.0f, -6.0f);
    glRotatef(angle, 1.0f, 1.0f, 0.0f); //How we rotate an object

    // Draw solid shape in green
    glColor3f(0.8f, 1.0f, 0.0f);

    glutSolidCube(1.5); //glutSolidCube(size)
    //glutSolidSphere(1.0, 30, 30); //glutSolidSphere(radius, slice, stacks)
    // glutSolidCone(1.0, 2.0, 30, 30); //glutSolidCone(Base, Height, slice, stacks)
    // glutSolidTorus(0.3, 0.7, 30, 30); //glutSolidTorus(innerRadius, outerRadius, nsides, rings)

    // Draw black wireframe outline
    // It is used for double buffering. OpenGL uses two buffers: Front Buffer: Displays the current image on the screen.
    //Back Buffer: Where OpenGL draws the next frame.
    glColor3f(0.0f, 0.0f, 0.0f);
    glPolygonMode(GL_FRONT_AND_BACK, GL_LINE);
    glLineWidth(2.0f);

    glutWireCube(1.5);
    //glutWireSphere(1.0, 30, 30);
    //glutWireCone(1.0, 2.0, 30, 30);
    //glutWireTorus(0.3, 0.7, 30, 30);

    // Restore polygon mode
    glPolygonMode(GL_FRONT_AND_BACK, GL_FILL);
    glutSwapBuffers();
}

void idle() {
    angle += 0.08f;
    if (angle > 360)
    angle -= 360; //This is equivalent to (angle=angle-360); The condition is true, so: 360.08-360=0.08. The angle becomes 0.08° again.
    glutPostRedisplay();
}

int main(int argc, char** argv) {
    glutInit(&argc, argv);
    glutInitDisplayMode(GLUT_DOUBLE | GLUT_RGB | GLUT_DEPTH);
    glutInitWindowSize(600, 600);
    glutCreateWindow("3D Shape Viewer");

    init();
    glutDisplayFunc(display);
    glutIdleFunc(idle);
    glutMainLoop();

    return 0;
}

